import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, calculateDueDate } from './dates.js';

/**
 * Check if a quantity is a positive integer.
 * @param {unknown} qty
 * @returns {boolean}
 */
function isValidQty(qty) {
  return Number.isInteger(qty) && qty > 0;
}

/**
 * Check if a discount percent is a number from 0 to 100.
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscountPercent(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Check if payment terms are valid.
 * @param {unknown} terms
 * @returns {boolean}
 */
function isValidTerms(terms) {
  return terms === 'NET14' || terms === 'NET30' || terms === 'EOM';
}

/**
 * Check if an amount is a positive integer (in cents).
 * @param {unknown} amount
 * @returns {boolean}
 */
function isValidAmount(amount) {
  return Number.isInteger(amount) && amount > 0;
}

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice(invoice) {
  const { customerId, issueDate, lines, terms } = invoice;
  const normalizedCustomerId = normalizeId(customerId);
  const normalizedTerms = terms ?? 'NET30';

  // Validate date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  if (!isValidTerms(normalizedTerms)) return fail('TERMS_INVALID');

  // Calculate due date
  const dueDate = calculateDueDate(issueDate, normalizedTerms);
  if (!dueDate) return fail('TERMS_INVALID');

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const customer = customerResult.value;
  const enrichedLines = [];
  for (const line of lines) {
    const { sku, qty } = line;
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];

    // Validate qty
    if (!isValidQty(qty)) return fail('QTY_INVALID');

    // Validate discount percent
    if (!isValidDiscountPercent(discountPercent)) return fail('DISCOUNT_INVALID');

    // Get product from catalogue
    const productResult = getProduct(sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms: normalizedTerms,
    dueDate,
  });
}

/**
 * Calculate the total for a single line item (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  return roundCents(total * discountPercent / 100);
}

/**
 * Calculate the VAT for a single line item (on amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  return roundCents(amountAfterDiscount * line.vatRate / 100);
}

/**
 * Calculate subtotal, discount, vat, voucher and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or update a line on an invoice. If the SKU exists, increase its qty; otherwise add a new line.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} lineToAdd
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, lineToAdd) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const { sku, qty } = lineToAdd;

  // Validate qty
  if (!isValidQty(qty)) return fail('QTY_INVALID');

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const discountPercent = lineToAdd.discountPercent !== undefined ? lineToAdd.discountPercent : TIER_DISCOUNTS[customer.tier];

  // Validate discount percent
  if (!isValidDiscountPercent(discountPercent)) return fail('DISCOUNT_INVALID');

  // Get product from catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Find existing line with this SKU
  const existingLine = newLines.find((line) => line.sku === sku);

  if (existingLine) {
    // Update existing line
    existingLine.qty += qty;
    existingLine.discountPercent = discountPercent;
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if line exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if it's the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without the removed line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} voucherToApply
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, voucherToApply) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if voucher already exists
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  const { code, amount } = voucherToApply;

  // Validate amount
  if (!isValidAmount(amount)) return fail('AMOUNT_INVALID');

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

/**
 * Issue a draft invoice by assigning it a number and changing its status to 'issued'.
 * @param {{ status: string, issueDate: string, lines: Array, customerId: string }} invoice
 * @param {string[]} existingNumbers - Array of previously issued invoice numbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check if invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Generate the next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

